package io.github.aayush10016.trail.identity.domain.port;

import io.github.aayush10016.trail.identity.domain.model.EmailActionTokenHash;

/**
 * Outbound port for hashing raw email action tokens before persistence.
 */
public interface EmailActionTokenHashingPolicy {

    /**
     * Hashes a raw token for storage or lookup.
     *
     * @param rawToken raw token presented by a user or generated by Trail
     * @return token hash
     */
    EmailActionTokenHash hash(String rawToken);
}
